/* v142.5: phone-safe Reader source selector closure. Short labels remain the
   canonical phone labels. The three source buttons use a real grid and never
   rely on clipping to avoid overlap. At Grand / Très grand, the source grid
   moves to its own row so the user's requested typography is preserved. */
@media(max-width:420px){
  .source-mode-bar.reader-context-bar{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;gap:4px;padding-left:4px;padding-right:4px;overflow:visible;}
  .reader-context-back{padding-left:8px;padding-right:8px;}
  .reader-context-bar .source-mode-segment{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));width:100%;min-width:0;flex:none;}
  .reader-context-bar .source-mode-btn{width:100%;min-width:0;padding-left:4px;padding-right:4px;letter-spacing:.01em;}
  .reader-context-bar .reader-source-long{display:none;}
  .reader-context-bar .reader-source-short{display:inline;}
}
/* Grand and Très grand use a separate selector row. This is a structural
   fallback: no font reduction, no truncation, no overflow masking. */
@media(max-width:420px){
  html[data-text-level="large"] .source-mode-bar.reader-context-bar,
  html[data-text-level="xlarge"] .source-mode-bar.reader-context-bar{grid-template-columns:1fr;align-items:stretch;}
  html[data-text-level="large"] .reader-context-back,
  html[data-text-level="xlarge"] .reader-context-back{justify-self:start;}
}
